15	// TestFinalizeExitedSessions finalizes an ACTIVE session whose owner process is
16	// gone, and leaves an ACTIVE session without a recorded owner untouched.
17	//
18	// Not parallel: setupAttachTestRepo uses t.Chdir.
19	func TestFinalizeExitedSessions(t *testing.T) {
20		setupAttachTestRepo(t)
21		ctx := context.Background()
22	
23		store, err := session.NewStateStore(ctx)
24		if err != nil {
25			t.Fatal(err)
26		}
27	
28		// Owner with a mismatched start fingerprint reads as a reused (dead) PID, a
29		// deterministic "agent exited" signal on linux/darwin.
30		exited := &session.State{
31			SessionID: "exited-session",
32			Phase:     session.PhaseActive,
33			StartedAt: time.Now(),
34			Owner:     &proclive.Identity{PID: os.Getpid(), Start: "bogus-start-fingerprint"},
35		}
36		// No owner recorded: must be left alone (liveness unknown → timeout fallback).
37		noOwner := &session.State{
38			SessionID: "no-owner-session",
39			Phase:     session.PhaseActive,
40			StartedAt: time.Now(),
41		}
42		for _, s := range []*session.State{exited, noOwner} {
43			if err := store.Save(ctx, s); err != nil {
44				t.Fatalf("save %s: %v", s.SessionID, err)
45			}
46		}
47	
48		states, err := store.List(ctx)
49		if err != nil {
50			t.Fatal(err)
51		}
52	
53		if n := finalizeExitedSessions(ctx, states); n != 1 {
54			t.Fatalf("finalizeExitedSessions = %d, want 1", n)
55		}
56	
57		// The exited session is now ended on disk.
58		got, err := store.Load(ctx, "exited-session")
59		if err != nil {
60			t.Fatal(err)
61		}
62		if got.EndedAt == nil {
63			t.Error("exited session EndedAt = nil, want set")
64		}
65		if got.Phase != session.PhaseEnded {
66			t.Errorf("exited session Phase = %q, want %q", got.Phase, session.PhaseEnded)
67		}
68	
69		// The owner-less session is untouched.
70		got, err = store.Load(ctx, "no-owner-session")
71		if err != nil {
72			t.Fatal(err)
73		}
74		if got.EndedAt != nil {
75			t.Error("no-owner session EndedAt set, want nil (left active)")
76		}
77	}
78	
79	// TestFinalizeExitedSessions_RevalidatesUnderLock guards against the
80	// time-of-check/time-of-use race: the sweep must re-check OwnerExited on the
81	// freshly-loaded state, not act on a stale list snapshot. Here the on-disk
82	// state has a LIVE owner while the snapshot passed to the sweep carries a dead
83	// one (as if a turn revived the session after the list was taken).
84	//
85	// Not parallel: setupAttachTestRepo uses t.Chdir.
86	func TestFinalizeExitedSessions_RevalidatesUnderLock(t *testing.T) {
87		setupAttachTestRepo(t)
88		ctx := context.Background()
89	
90		liveOwner, ok := proclive.ResolveOwner()
91		if !ok {
92			t.Skip("no stable process owner resolvable in this environment")
93		}
94	
95		store, err := session.NewStateStore(ctx)
96		if err != nil {
97			t.Fatal(err)
98		}
99		if err := store.Save(ctx, &session.State{
100			SessionID: "revived",
101			Phase:     session.PhaseActive,
102			StartedAt: time.Now(),
103			Owner:     &liveOwner, // on disk: a live owner
104		}); err != nil {
105			t.Fatal(err)
106		}
107	
108		// Stale snapshot the sweep sees: same session, but with a dead owner.
